#!/usr/bin/env node
/**
 * Adds shadcn-vue components to src/components/ui/ and keeps the repo's rules intact.
 *
 *   pnpm ui:add <component> [<component> ...]   add components
 *   pnpm ui:add --mark-only                     only restore the ts-nocheck line (no network)
 *
 * Why a script: generated files fail `exactOptionalPropertyTypes`, so each carries a ts-nocheck
 * line as the first line of its script block, and a fresh `add` removes it (P0-T9 decisions). The
 * `ui-files-marked` rule in scripts/check-arch.mjs fails when a generated file lacks the line.
 *
 * What it does:
 *   1. Runs `shadcn-vue@2.9.0 add <components> --yes --overwrite` (2.9.0 is the version Phase 0
 *      tested). It never runs `init`, which rewrites src/styles/tokens.css.
 *   2. Puts back src/styles/tokens.css, components.json and src/lib/utils.ts if `add` changed
 *      them, and says so. The changed copy goes to a temp folder to merge by hand if it matters.
 *   3. Gives every .vue file under src/components/ui/ the ts-nocheck line. Running it twice
 *      changes nothing the second time.
 *
 * Exit 0 on success, 1 when the add fails, 2 on bad usage.
 */
import { spawnSync } from 'node:child_process'
import { existsSync, mkdtempSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const SHADCN_VERSION = '2.9.0'
const UI_DIR = 'src/components/ui'

// The same text is checked by the `ui-files-marked` rule in scripts/check-arch.mjs.
const MARKER = '// @ts-nocheck -- generated by shadcn-vue, fails exactOptionalPropertyTypes'

/** Files `add` must leave alone. `init` rewrites the first; the others are ours. */
const PROTECTED = ['src/styles/tokens.css', 'components.json', 'src/lib/utils.ts']

/**
 * Edits a fresh `add` would undo, applied after it: a generated file that breaks one of the repo's
 * rules gets the smallest change that satisfies it. Each `from` must still be there, or the
 * generator changed and the entry needs another look.
 */
const FIXES = [
  {
    // `hsl(...)` is a colour literal outside src/styles/ (no-hard-coded-colors), and the token it
    // wraps is not an hsl channel list anyway.
    file: `${UI_DIR}/sonner/Sonner.vue`,
    from: "'--gray2': 'hsl(var(--popover) / 0.9)',",
    to: "'--gray2': 'var(--popover)',",
  },
]

/** An opening <script ...> tag; attribute values may hold `>` (generic="T extends A<B>"). */
const SCRIPT_OPEN = /<script\b(?:"[^"]*"|'[^']*'|[^>"'])*>/g

function usage(problem) {
  console.error(
    `${problem}\nusage: pnpm ui:add <component> [<component> ...]\n       pnpm ui:add --mark-only`,
  )
  return 2
}

/** Relative posix paths of every .vue file under `dir`. */
function vueFiles(root, dir) {
  const out = []
  const abs = join(root, dir)
  if (!existsSync(abs)) return out
  for (const entry of readdirSync(abs, { withFileTypes: true })) {
    const rel = `${dir}/${entry.name}`
    if (entry.isDirectory()) out.push(...vueFiles(root, rel))
    else if (entry.name.endsWith('.vue')) out.push(rel)
  }
  return out
}

/**
 * `text` with the marker as the first line of every <script> block. A different ts-nocheck line
 * there is replaced. The file's own line endings are kept.
 */
function markScripts(text) {
  const eol = text.includes('\r\n') ? '\r\n' : '\n'
  let out = ''
  let last = 0
  for (const open of text.matchAll(SCRIPT_OPEN)) {
    if (/\bsrc\s*=/.test(open[0])) continue
    const tagEnd = open.index + open[0].length
    // The block starts after the line break that follows the tag.
    const bodyStart = tagEnd + (text.startsWith('\r\n', tagEnd) ? 2 : text[tagEnd] === '\n' ? 1 : 0)
    const newline = text.indexOf('\n', bodyStart)
    const lineEnd = newline === -1 ? text.length : newline
    const firstLine = text.slice(bodyStart, lineEnd).replace(/\r$/, '')
    if (firstLine === MARKER) continue
    out += text.slice(last, tagEnd) + eol + MARKER + eol
    // Another ts-nocheck line is replaced; anything else stays below the marker.
    last = /^\s*\/\/\s*@ts-nocheck\b/.test(firstLine)
      ? Math.min(lineEnd + 1, text.length)
      : bodyStart
  }
  return out + text.slice(last)
}

/** Applies FIXES. Returns the files it changed; warns about an entry whose text is gone. */
function applyFixes(root) {
  const changed = []
  for (const { file, from, to } of FIXES) {
    const path = join(root, file)
    if (!existsSync(path)) continue
    const before = readFileSync(path, 'utf8')
    if (before.includes(to)) continue
    if (!before.includes(from)) {
      console.error(`warning: the fix for ${file} no longer matches; check the file by hand`)
      continue
    }
    writeFileSync(
      path,
      before.replace(from, () => to),
    )
    changed.push(file)
  }
  return changed
}

/** Marks every generated .vue file. Returns the files it changed. */
function markAll(root) {
  const changed = []
  for (const rel of vueFiles(root, UI_DIR)) {
    const path = join(root, rel)
    const before = readFileSync(path, 'utf8')
    const after = markScripts(before)
    if (after !== before) {
      writeFileSync(path, after)
      changed.push(rel)
    }
  }
  return changed
}

/** Runs shadcn-vue through pnpm. The component names are checked, so a shell string is safe. */
function runAdd(root, names) {
  const command = `pnpm dlx shadcn-vue@${SHADCN_VERSION} add ${names.join(' ')} --yes --overwrite`
  console.log(`> ${command}`)
  return spawnSync(command, { cwd: root, shell: true, stdio: 'inherit' })
}

/** Puts back any protected file `add` changed. Returns nothing; it reports on stderr. */
function restoreProtected(root, before) {
  for (const [rel, original] of before) {
    const path = join(root, rel)
    const now = existsSync(path) ? readFileSync(path) : null
    if (original === null ? now === null : now?.equals(original)) continue
    const keep = join(mkdtempSync(join(tmpdir(), 'ui-add-')), rel.replace(/[\\/]/g, '__'))
    if (now) writeFileSync(keep, now)
    if (original) writeFileSync(path, original)
    console.error(
      `warning: shadcn-vue changed ${rel}; restored it. Its version is saved at ${keep} ` +
        'in case the component needs something from it.',
    )
  }
}

function main(argv) {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
  const names = []
  let markOnly = false
  for (const arg of argv) {
    if (arg === '--mark-only') markOnly = true
    else if (arg.startsWith('-')) return usage(`unknown option ${arg}`)
    else if (!/^[a-z0-9][a-z0-9-]*$/.test(arg)) {
      return usage(`"${arg}" is not a plain component name like "dropdown-menu"`)
    } else names.push(arg)
  }
  if (markOnly && names.length > 0) return usage('--mark-only takes no component names')
  if (!markOnly && names.length === 0) return usage('name at least one component')

  let failure = ''
  if (!markOnly) {
    const before = new Map(
      PROTECTED.map((rel) => [
        rel,
        existsSync(join(root, rel)) ? readFileSync(join(root, rel)) : null,
      ]),
    )

    const result = runAdd(root, names)
    if (result.error) failure = `could not start pnpm: ${result.error.message}`
    else if (result.status !== 0) failure = `shadcn-vue add exited with ${String(result.status)}`

    restoreProtected(root, before)

    if (!failure) {
      const missing = names.find((name) => !existsSync(join(root, UI_DIR, name)))
      if (missing) failure = `shadcn-vue reported success but ${UI_DIR}/${missing}/ does not exist`
    }
  }

  const fixed = applyFixes(root)
  if (fixed.length > 0) console.log(`fixes applied to: ${fixed.join(', ')}`)
  const marked = markAll(root)
  console.log(
    marked.length === 0
      ? 'ts-nocheck line: already present in every generated .vue file'
      : `ts-nocheck line: added to ${String(marked.length)} file(s)`,
  )

  if (failure) {
    console.error(`ui:add failed: ${failure}`)
    return 1
  }
  return 0
}

process.exitCode = main(process.argv.slice(2))
